import libtmux, time, sys, os
def capture(pane):
    return "\n".join(pane.capture_pane())
def run_session(cmd, keys_sequence=None, wait=0.8, name="test", width=120, height=40):
    server = libtmux.Server()
    try:
        old = server.sessions.get(session_name=name, default=None)
        if old: old.kill()
    except Exception as e:
        pass
    session = server.new_session(session_name=name, kill_session=True, attach=False, window_width=width, window_height=height)
    window = session.active_window
    pane = window.active_pane
    pane.send_keys(cmd, enter=True)
    time.sleep(wait)
    print("=== initial ===")
    print(capture(pane))
    if keys_sequence:
        for label, key, literal in keys_sequence:
            print(f"\n=== after {label} ({key!r}) ===")
            if literal:
                pane.send_keys(key, enter=False, literal=True)
            else:
                pane.send_keys(key, enter=False)
            time.sleep(0.5)
            print(capture(pane))
    # try quit
    try:
        pane.send_keys("q", enter=False, literal=True)
        time.sleep(0.5)
        print("\n=== after q ===")
        print(capture(pane))
    except Exception as e:
        print(e)
    try:
        session.kill()
    except: pass

if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv)>1 else "cd /tmp/test1 && TERM=xterm-256color EDITOR=vim /workspace/executable hello"
    run_session(cmd)
