        f.write(f"\n=== scroll {i} ===\n"+cap())
        # scroll down many times? send j multiple
        for _ in range(5): send("j",lit=True)
    # scroll right
    for i in range(3):
        send("l",lit=True)
        f.write(f"\n=== right {i} ===\n"+cap())
    for i in range(3):
        send("h",lit=True)
        f.write(f"\n=== left {i} ===\n"+cap())
kill()
print("done")
