use anyhow::{anyhow, Context};
use std::fmt;
use std::process::Command;

pub const EDITOR_VARIANTS: &[&str] = &[
    "vim", "neovim", "nvim", "nano", "code", "vscode", "code-insiders", "emacs",
    "emacsclient", "hx", "helix", "subl", "sublime-text", "micro", "intellij", "goland",
    "pycharm", "less", "fresh",
];

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Editor {
    Vim,
    Neovim,
    Nvim,
    Nano,
    Code,
    Vscode,
    CodeInsiders,
    Emacs,
    Emacsclient,
    Hx,
    Helix,
    Subl,
    SublimeText,
    Micro,
    Intellij,
    Goland,
    Pycharm,
    Less,
    Fresh,
}

#[derive(Debug)]
struct InvalidEditorVariant(String);

impl fmt::Display for InvalidEditorVariant {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "invalid variant: {}", self.0)
    }
}

impl std::error::Error for InvalidEditorVariant {}

impl Editor {
    pub fn from_name(name: &str) -> Result<Self, InvalidEditorVariant> {
        Ok(match name {
            "vim" => Self::Vim,
            "neovim" => Self::Neovim,
            "nvim" => Self::Nvim,
            "nano" => Self::Nano,
            "code" => Self::Code,
            "vscode" => Self::Vscode,
            "code-insiders" => Self::CodeInsiders,
            "emacs" => Self::Emacs,
            "emacsclient" => Self::Emacsclient,
            "hx" => Self::Hx,
            "helix" => Self::Helix,
            "subl" => Self::Subl,
            "sublime-text" => Self::SublimeText,
            "micro" => Self::Micro,
            "intellij" => Self::Intellij,
            "goland" => Self::Goland,
            "pycharm" => Self::Pycharm,
            "less" => Self::Less,
            "fresh" => Self::Fresh,
            other => return Err(InvalidEditorVariant(other.to_string())),
        })
    }

    fn command(&self, file_name: &str, line_number: u64) -> (String, Vec<String>) {
        let line = line_number.to_string();
        let plus_line = format!("+{}", line_number);
        let file_line = format!("{}:{}", file_name, line_number);
        match self {
            Self::Vim => ("vim".into(), vec![plus_line, file_name.into()]),
            Self::Neovim | Self::Nvim => ("nvim".into(), vec![plus_line, file_name.into()]),
            Self::Nano => ("nano".into(), vec![plus_line, file_name.into()]),
            Self::Code | Self::Vscode => ("code".into(), vec!["-g".into(), file_line]),
            Self::CodeInsiders => ("code-insiders".into(), vec!["-g".into(), file_line]),
            Self::Emacs => (
                "emacs".into(),
                vec!["-nw".into(), plus_line, file_name.into()],
            ),
            Self::Emacsclient => (
                "emacsclient".into(),
                vec!["-nw".into(), plus_line, file_name.into()],
            ),
            Self::Hx => ("hx".into(), vec![file_line]),
            Self::Helix => ("helix".into(), vec![file_line]),
            Self::Subl | Self::SublimeText => ("subl".into(), vec![file_line]),
            Self::Micro => ("micro".into(), vec![plus_line, file_name.into()]),
            Self::Intellij => (
                "idea".into(),
                vec!["--line".into(), line, file_name.into()],
            ),
            Self::Goland => (
                "goland".into(),
                vec!["--line".into(), line, file_name.into()],
            ),
            Self::Pycharm => (
                "pycharm".into(),
                vec!["--line".into(), line, file_name.into()],
            ),
            Self::Less => ("less".into(), vec![plus_line, file_name.into()]),
            Self::Fresh => ("fresh".into(), vec![file_line]),
        }
    }
}

#[derive(Debug)]
struct IncorrectCommand(String);

impl fmt::Display for IncorrectCommand {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl std::error::Error for IncorrectCommand {}

#[derive(Debug, Clone)]
pub enum FileOpener {
    Editor(Editor),
    Custom { program: String, args: String },
}

impl FileOpener {
    pub fn new(
        editor_arg: Option<&str>,
        custom_command: Option<&str>,
    ) -> anyhow::Result<Self> {
        if let Some(command) = custom_command {
            let parsed = parse_custom_command(command)
                .with_context(|| format!("Incorrect editor command: '{}'", command))?;
            return Ok(Self::Custom {
                program: parsed.0,
                args: parsed.1,
            });
        }

        if let Some(editor) = editor_arg {
            // Clap has already restricted this to a known name.
            return Ok(Self::Editor(
                Editor::from_name(editor).unwrap_or(Editor::Vim),
            ));
        }

        for var_name in ["IGREP_EDITOR", "VISUAL", "EDITOR"] {
            if let Ok(value) = std::env::var(var_name) {
                let base = value.rsplit('/').next().unwrap_or(&value);
                let editor = Editor::from_name(base).with_context(|| {
                    format!(
                        "\"{}\" read from ${}, possible variants: [{}]",
                        value,
                        var_name,
                        EDITOR_VARIANTS.join(", ")
                    )
                })?;
                return Ok(Self::Editor(editor));
            }
        }

        Ok(Self::Editor(Editor::Vim))
    }

    /// On failure to spawn (or wait for) the command, returns the program
    /// name to show in the status line.
    pub fn open(&self, file_name: &str, line_number: u64) -> Result<(), String> {
        let (program, args) = match self {
            Self::Editor(editor) => editor.command(file_name, line_number),
            Self::Custom { program, args } => {
                let replaced = args
                    .replace("{file_name}", file_name)
                    .replace("{line_number}", &line_number.to_string());
                let args: Vec<String> =
                    replaced.split_whitespace().map(|arg| arg.to_string()).collect();
                (program.clone(), args)
            }
        };

        match Command::new(&program).args(&args).status() {
            Ok(_) => Ok(()),
            Err(_) => Err(program),
        }
    }
}

fn parse_custom_command(command: &str) -> Result<(String, String), IncorrectCommand> {
    let Some((program, args)) = command.split_once(' ') else {
        return Err(IncorrectCommand(
            "Expected program and its arguments".to_string(),
        ));
    };
    if args.matches("{file_name}").count() != 1 {
        return Err(IncorrectCommand(
            "Expected one occurrence of '{file_name}'.".to_string(),
        ));
    }
    if args.matches("{line_number}").count() != 1 {
        return Err(IncorrectCommand(
            "Expected one occurrence of '{line_number}'.".to_string(),
        ));
    }
    let _ = anyhow!("");
    Ok((program.to_string(), args.to_string()))
}
RS
"}

