const TYPE_LIST: &str = include_str!("../type_list.txt");
const BUFFER_SIZE: usize = 65536;

#[derive(Debug)]
pub struct Error {
    kind: ErrorKind,
}

#[derive(Debug)]
enum ErrorKind {
    Regex(String),
    NotAllowed(String),
}

#[derive(Clone)]
pub struct PreparedSearch {
    overrides: Override,
    types: Types,
}

pub fn type_list() -> &'static str {
    TYPE_LIST
