pub fn prepare(config: &SearchConfig) -> anyhow::Result<PreparedSearch> {
    let overrides = build_overrides(&config.globs)?;
    let types = build_types(&config.type_matching, &config.type_not)?;
    Ok(PreparedSearch { overrides, types })
}

fn build_overrides(globs: &[String]) -> anyhow::Result<Override> {
    let mut builder = ignore::overrides::OverrideBuilder::new(".");
    for glob in globs {
        builder.add(glob)?;
    }
    Ok(builder.build()?)
}

fn build_types(select: &[String], negate: &[String]) -> anyhow::Result<Types> {
    let mut builder = TypesBuilder::new();
    for line in TYPE_LIST.lines() {
        if let Some((name, globs)) = line.split_once(": ") {
            for glob in globs.split(", ") {
                let _ = builder.add(name, glob);
            }
        }
    }
    for name in select {
        builder.select(name);
    }
    for name in negate {
        builder.negate(name);
    }
    Ok(builder.build()?)
}

struct MatcherInfo {
    regex: Regex,
}

fn build_matcher(config: &SearchConfig) -> Result<MatcherInfo, Error> {
    let effective_pattern = if config.fixed_strings {
        regex::escape(&config.pattern)
    } else {
        config.pattern.clone()
    };

    let case_insensitive = if config.ignore_case {
        true
    } else if config.smart_case {
        !has_uppercase_literal(&effective_pattern)
    } else {
        false
    };

    let wrapped = format!("(?:{})", effective_pattern);
    let built = build_bytes_regex(&wrapped, case_insensitive)
        .map_err(|err| Error { kind: ErrorKind::Regex(err.to_string()) });

    let regex = built.and_then(|regex| {
            if !config.multiline && pattern_has_newline_literal(&wrapped, case_insensitive) {
                return Err(Error { kind: ErrorKind::NotAllowed("\n".to_string()) });
            }
            Ok(regex)
        })
        .expect("Cannot build RegexMatcher");

    let search_regex = if config.word_regexp {
        let word_pattern = format!(r"(?:\b{{start-half}}(?:{})\b{{end-half}})", effective_pattern);
        build_bytes_regex(&word_pattern, case_insensitive).unwrap_or(regex)
    } else {
        regex
    };

    Ok(MatcherInfo { regex: search_regex })
}

fn build_bytes_regex(pattern: &str, case_insensitive: bool) -> Result<Regex, regex::Error> {
    RegexBuilder::new(pattern)
        .case_insensitive(case_insensitive)
        .multi_line(true)
        .dot_matches_new_line(false)
        .crlf(false)
        .octal(false)
        .unicode(true)
        .build()
}

struct UppercaseVisitor {
    found: bool,
}

impl ast::visit::Visitor for UppercaseVisitor {
    type Output = bool;
    type Err = std::convert::Infallible;

    fn finish(self) -> Result<Self::Output, Self::Err> {
        Ok(self.found)
    }

    fn visit_pre(&mut self, ast_node: &Ast) -> Result<(), Self::Err> {
        if let Ast::Literal(literal) = ast_node {
            if literal.c.is_uppercase() {
                self.found = true;
            }
        }
        Ok(())
    }

    fn visit_class_set_item_pre(
        &mut self,
        item: &ast::ClassSetItem,
    ) -> Result<(), Self::Err> {
        match item {
            ast::ClassSetItem::Literal(literal) => {
                if literal.c.is_uppercase() {
                    self.found = true;
                }
            }
            ast::ClassSetItem::Range(range) => {
                if range.start.c.is_uppercase() || range.end.c.is_uppercase() {
                    self.found = true;
                }
            }
            _ => {}
        }
        Ok(())
    }
}

fn has_uppercase_literal(pattern: &str) -> bool {
    let Ok(ast) = ast::parse::Parser::new().parse(pattern) else {
        return false;
    };
    ast::visit::visit(&ast, UppercaseVisitor { found: false }).unwrap_or(false)
}

struct NewlineVisitor {
    found: bool,
}

impl hir::visit::Visitor for NewlineVisitor {
    type Output = bool;
    type Err = std::convert::Infallible;

    fn finish(self) -> Result<Self::Output, Self::Err> {
        Ok(self.found)
    }

    fn visit_pre(&mut self, hir_node: &Hir) -> Result<(), Self::Err> {
        if let hir::HirKind::Literal(literal) = hir_node.kind() {
            if literal.as_ref().contains(&b'\n') {
                self.found = true;
            }
        }
        Ok(())
    }
}

fn pattern_has_newline_literal(pattern: &str, case_insensitive: bool) -> bool {
    let hir_result = regex_syntax::ParserBuilder::new()
        .utf8(false)
        .case_insensitive(case_insensitive)
        .multi_line(true)
        .dot_matches_new_line(false)
        .crlf(false)
        .octal(false)
        .unicode(true)
        .build()
        .parse(pattern);
    let Ok(hir) = hir_result else {
        return false;
    };
    hir::visit::visit(&hir, NewlineVisitor { found: false }).unwrap_or(false)
}

fn compare_paths(sort_by: SortBy, reverse: bool, a: &Path, b: &Path) -> Ordering {
    let ordering = match sort_by {
        SortBy::Path => a.cmp(b),
        SortBy::Modified => metadata_time(a, |m| m.modified()).cmp(&metadata_time(b, |m| m.modified())),
        SortBy::Created => metadata_time(a, |m| m.created()).cmp(&metadata_time(b, |m| m.created())),
        SortBy::Accessed => metadata_time(a, |m| m.accessed()).cmp(&metadata_time(b, |m| m.accessed())),
    };
    if reverse {
        ordering.reverse()
    } else {
        ordering
    }
}

fn metadata_time<F>(path: &Path, getter: F) -> SystemTime
where
    F: Fn(&std::fs::Metadata) -> std::io::Result<SystemTime>,
{
    std::fs::metadata(path)
        .and_then(|metadata| getter(&metadata))
        .unwrap_or(SystemTime::UNIX_EPOCH)
}

pub fn run_search(
    config: SearchConfig,
    prepared: PreparedSearch,
    sender: Sender<SearchEvent>,
) {
    let matcher = build_matcher(&config).expect("matcher was built");
    let regex = matcher.regex;

    let first_path: PathBuf = config
        .paths
        .first()
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));
    let mut builder = WalkBuilder::new(&first_path);
    for path in config.paths.iter().skip(1) {
        builder.add(path);
    }

    builder
        .hidden(!config.hidden)
        .follow_links(config.follow)
        .overrides(prepared.overrides)
        .types(prepared.types);

    if let Some((sort_by, reverse)) = config.sort {
        builder.sort_by_file_path(move |a, b| compare_paths(sort_by, reverse, a, b));
    }

    let walker = builder.build_parallel();
    let multiline = config.multiline;
    walker.run(|| {
        let sender = sender.clone();
        let regex = regex.clone();
        Box::new(move |entry| {
            let Ok(entry) = entry else {
                return WalkState::Continue;
            };
            let is_file = entry
                .file_type()
                .map(|file_type| file_type.is_file())
                .unwrap_or(false);
            if !is_file {
                return WalkState::Continue;
            }

            let path = entry.path();
            let matches = if multiline {
                search_file_multiline(path, &regex)
            } else {
                search_file_lines(path, &regex)
            };

            if let Some(matches) = matches {
                if !matches.is_empty() {
                    let file_entry = FileEntry {
                        file_name: path.to_string_lossy().to_string(),
                        matches,
                    };
                    if sender.send(SearchEvent::File(file_entry)).is_err() {
                        return WalkState::Quit;
                    }
                }
            }
            WalkState::Continue
        })
    });

    let _ = sender.send(SearchEvent::Finished);
}

fn search_file_lines(path: &Path, regex: &Regex) -> Option<Vec<MatchEntry>> {
    let file = File::open(path).ok()?;
    let mut reader = ChunkReader::new(BufReader::new(file));
    let mut matches = Vec::new();
    let mut line_number: u64 = 0;

    while let Some(chunk) = reader.next_chunk() {
        if chunk.contains(&0) {
            break;
        }
        let mut offset = 0usize;
        let mut stop_file = false;
        while offset < chunk.len() {
            let (content_end, next_offset) =
                match chunk[offset..].iter().position(|byte| *byte == b'\n') {
                    Some(pos) => (offset + pos, offset + pos + 1),
                    None => (chunk.len(), chunk.len()),
                };
            line_number += 1;
            let line_bytes = &chunk[offset..content_end];
            let found: Vec<(usize, usize)> = regex
                .find_iter(line_bytes)
                .map(|m| (m.start(), m.end()))
                .collect();
            if !found.is_empty() {
                match std::str::from_utf8(line_bytes) {
                    Ok(text) => matches.push(MatchEntry {
                        line_number,
                        text: text.to_string(),
                        ranges: found,
                    }),
                    Err(_) => {
                        stop_file = true;
                        break;
                    }
                }
            }
            offset = next_offset;
        }
        if stop_file {
            break;
        }
    }

    Some(matches)
}

struct ChunkReader {
    reader: BufReader<File>,
    leftover: Vec<u8>,
    eof: bool,
}

impl ChunkReader {
    fn new(reader: BufReader<File>) -> Self {
        Self { reader, leftover: Vec::new(), eof: false }
    }

    fn next_chunk(&mut self) -> Option<Vec<u8>> {
        if self.eof && self.leftover.is_empty() {
            return None;
        }
        let mut buffer = std::mem::take(&mut self.leftover);

        if !self.eof && buffer.len() < BUFFER_SIZE {
            let wanted = BUFFER_SIZE - buffer.len();
            let mut limited = (&mut self.reader).take(wanted as u64);
            match limited.read_to_end(&mut buffer) {
                Ok(read) => {
                    if read < wanted {
                        self.eof = true;
                    }
                }
                Err(_) => {
                    self.eof = true;
                }
            }
        }

        if buffer.is_empty() {
            return None;
        }

        if self.eof {
            return Some(buffer);
        }

        match buffer.iter().rposition(|byte| *byte == b'\n') {
            Some(pos) => {
                self.leftover = buffer.split_off(pos + 1);
                Some(buffer)
            }
            None => {
                // A single line longer than the buffer: keep reading to its end.
                let mut extra = Vec::new();
                match self.reader.read_until_adapter(&mut extra) {
                    Ok(0) => {
                        self.eof = true;
                    }
                    Ok(_) => {
                        buffer.extend(extra);
                        if !buffer.ends_with(b"\n") {
                            self.eof = true;
                        }
                    }
                    Err(_) => {
                        self.eof = true;
                    }
                }
                Some(buffer)
            }
        }
    }
}

trait ReadUntilAdapter {
    fn read_until_adapter(&mut self, out: &mut Vec<u8>) -> std::io::Result<usize>;
}

impl ReadUntilAdapter for BufReader<File> {
    fn read_until_adapter(&mut self, out: &mut Vec<u8>) -> std::io::Result<usize> {
        use std::io::BufRead;
        self.read_until(b'\n', out)
    }
}

struct LineInfo {
    start: usize,
    content_end: usize,
    next_start: usize,
}

fn line_infos(data: &[u8]) -> Vec<LineInfo> {
    let mut lines = Vec::new();
    let mut start = 0usize;
    while start < data.len() {
        match data[start..].iter().position(|byte| *byte == b'\n') {
            Some(pos) => {
                let content_end = start + pos;
                let next_start = content_end + 1;
                lines.push(LineInfo { start, content_end, next_start });
                start = next_start;
            }
            None => {
                lines.push(LineInfo { start, content_end: data.len(), next_start: data.len() });
                break;
            }
        }
    }
    lines
}

fn line_index_for(lines: &[LineInfo], data_len: usize, position: usize) -> Option<usize> {
    if position >= data_len {
        if data_len == 0 {
            return None;
        }
        // A position at the very end belongs to the last, unterminated line.
        // If the data ends in a newline it is a virtual following line.
        if lines
            .last()
            .map(|line| line.next_start > line.content_end)
            .unwrap_or(false)
        {
            return None;
        }
        return lines.len().checked_sub(1);
    }
    lines.iter().position(|line| position >= line.start && position < line.next_start)
}

fn binary_chunk_contains_nul(data: &[u8], position: usize) -> bool {
    // Split the data into line-aligned chunks of at most BUFFER_SIZE bytes,
    // mirroring the line-mode reader, and see whether the chunk containing
    // `position` contains a NUL byte.
    let mut start = 0usize;
    while start < data.len() {
        let mut end = usize::min(data.len(), start + BUFFER_SIZE);
        if end < data.len() {
            match data[start..end].iter().rposition(|byte| *byte == b'\n') {
                Some(pos) => end = start + pos + 1,
                None => {
                    // long line: extend to its end
                    match data[end..].iter().position(|byte| *byte == b'\n') {
                        Some(pos) => end = end + pos + 1,
                        None => end = data.len(),
                    }
                }
            }
        }
        if position >= start && position < end {
            return data[start..end].contains(&0);
        }
        if end == start {
            break;
        }
        start = end;
    }
    false
}

fn search_file_multiline(path: &Path, regex: &Regex) -> Option<Vec<MatchEntry>> {
    let data = std::fs::read(path).ok()?;
    if data.is_empty() {
        // An empty pattern still has no lines to report in an empty file.
        return Some(Vec::new());
    }
    let lines = line_infos(&data);

    #[derive(Clone)]
    struct Group {
        start_line: usize,
        end_line: usize,
        ranges: Vec<(usize, usize)>,
    }

    let mut groups: Vec<Group> = Vec::new();
    for found in regex.find_iter(&data) {
        let (start, end) = (found.start(), found.end());
        let (start_line, end_line) = if start == end {
            let Some(line) = line_index_for(&lines, data.len(), start) else {
                continue;
            };
