fn build_overrides(globs: &[String]) -> anyhow::Result<Override> {
    let mut builder = ignore::overrides::OverrideBuilder::new(".");
    for glob in globs {
        builder.add(glob)?;
    }
    Ok(builder.build()?)
}

fn build_types(select: &[String], negate: &[String]) -> anyhow::Result<Types> {
    let mut builder = TypesBuilder::new();
    for line in TYPE_LIST.lines() {
        if let Some((name, globs)) = line.split_once(": ") {
            for glob in globs.split(", ") {
                let _ = builder.add(name, glob);
            }
        }
    }
    for name in select {
        builder.select(name);
    }
    for name in negate {
        builder.negate(name);
    }
    Ok(builder.build()?)
