use crate::args::Theme;
use ratatui::prelude::*;

fn rgb(r: u8, g: u8, b: u8) -> Color {
    Color::Rgb(r, g, b)
}

#[derive(Clone, Copy)]
pub struct Palette {
    pub foreground: Color,
    pub comment: Color,
    pub red: Color,
    pub orange: Color,
    pub yellow: Color,
    pub green: Color,
    pub cyan: Color,
    pub blue: Color,
    pub purple: Color,
}

pub fn palette(theme: &Theme) -> Palette {
    match theme {
        Theme::Dark => Palette {
            foreground: rgb(192, 197, 206),
            comment: rgb(101, 115, 126),
            red: rgb(191, 97, 106),
            orange: rgb(208, 135, 112),
            yellow: rgb(235, 203, 139),
            green: rgb(163, 190, 140),
            cyan: rgb(150, 181, 180),
            blue: rgb(143, 161, 179),
            purple: rgb(180, 142, 173),
        },
        Theme::Light => Palette {
            foreground: rgb(79, 91, 102),
            comment: rgb(167, 173, 186),
            red: rgb(191, 97, 106),
            orange: rgb(208, 135, 112),
            yellow: rgb(235, 203, 139),
            green: rgb(163, 190, 140),
            cyan: rgb(150, 181, 180),
            blue: rgb(143, 161, 179),
            purple: rgb(180, 142, 173),
        },
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Lang {
    Plain,
    Hash,
    Slash,
    Rust,
    Python,
    Html,
}

pub struct Highlighter {
    palette: Palette,
    lang: Lang,
    in_block_comment: bool,
    in_triple: Option<&'static str>,
}

impl Highlighter {
    pub fn new(file_name: &str, first_line: &str, theme: &Theme) -> Self {
        Self {
            palette: palette(theme),
            lang: detect_lang(file_name, first_line),
            in_block_comment: false,
            in_triple: None,
        }
    }

    pub fn highlight_line(&mut self, line: &str) -> Line<'static> {
        if self.lang == Lang::Plain {
            return Line::from(Span::styled(
                line.to_string(),
                Style::default().fg(self.palette.foreground),
            ));
        }
        let spans = self.tokenize(line);
        if spans.is_empty() {
            Line::from(Span::styled(
                String::new(),
                Style::default().fg(self.palette.foreground),
            ))
        } else {
            Line::from(spans)
        }
    }

    fn tokenize(&mut self, line: &str) -> Vec<Span<'static>> {
        let mut spans: Vec<Span<'static>> = Vec::new();
        let bytes = line.as_bytes();
        let mut i = 0usize;

        let push = |spans: &mut Vec<Span<'static>>, text: &str, color: Color| {
            if !text.is_empty() {
                spans.push(Span::styled(text.to_string(), Style::default().fg(color)));
            }
        };

        while i < bytes.len() {
            if self.in_block_comment {
                if let Some(end) = line[i..].find("*/") {
                    let j = i + end + 2;
                    push(&mut spans, &line[i..j], self.palette.comment);
                    i = j;
                    self.in_block_comment = false;
                } else {
                    push(&mut spans, &line[i..], self.palette.comment);
                    break;
                }
                continue;
            }

            if let Some(quote) = self.in_triple {
                if let Some(end) = line[i..].find(quote) {
                    let j = i + end + quote.len();
                    push(&mut spans, &line[i..j], self.palette.green);
                    i = j;
                    self.in_triple = None;
                } else {
                    push(&mut spans, &line[i..], self.palette.green);
                    break;
                }
                continue;
            }

            let rest = &line[i..];

            if self.lang == Lang::Html && rest.starts_with("<!--") {
                if let Some(end) = rest.find("-->") {
                    push(&mut spans, &rest[..end + 3], self.palette.comment);
                    i += end + 3;
                } else {
                    push(&mut spans, rest, self.palette.comment);
                    break;
                }
                continue;
            }

            if (self.lang == Lang::Slash || self.lang == Lang::Rust) && rest.starts_with("/*") {
                if let Some(end) = rest[2..].find("*/") {
                    let j = 2 + end + 2;
                    push(&mut spans, &rest[..j], self.palette.comment);
                    i += j;
                } else {
                    push(&mut spans, rest, self.palette.comment);
                    self.in_block_comment = true;
                    break;
                }
                continue;
            }

            if is_line_comment(self.lang, rest) {
                push(&mut spans, rest, self.palette.comment);
                break;
            }

            if self.lang == Lang::Python && (rest.starts_with("\"\"\"") || rest.starts_with("'''")) {
                let quote = if rest.starts_with("\"\"\"") { "\"\"\"" } else { "'''" };
                if let Some(end) = rest[3..].find(quote) {
                    let j = 3 + end + 3;
                    push(&mut spans, &rest[..j], self.palette.green);
                    i += j;
                } else {
                    push(&mut spans, rest, self.palette.green);
                    self.in_triple = Some(quote);
                    break;
                }
                continue;
            }

            let ch = rest.chars().next().unwrap();

            if ch == '"' || ch == '\'' || ch == '`' {
                let mut j = ch.len_utf8();
                let chars: Vec<(usize, char)> = rest.char_indices().skip(1).collect();
                let mut closed = false;
                let mut prev = '\0';
                for (idx, c) in chars {
                    if c == ch && prev != '\\' {
                        j = idx + c.len_utf8();
                        closed = true;
                        break;
                    }
                    prev = c;
                    j = idx + c.len_utf8();
                }
                if !closed {
                    j = rest.len();
                }
                push(&mut spans, &rest[..j], self.palette.green);
                i += j;
                continue;
            }

            if ch.is_ascii_digit() {
                let mut j = 0usize;
                for c in rest.chars() {
                    if c.is_ascii_alphanumeric() || c == '.' || c == '_' {
                        j += c.len_utf8();
                    } else {
                        break;
                    }
                }
                push(&mut spans, &rest[..j], self.palette.orange);
                i += j;
                continue;
            }

            if ch.is_alphabetic() || ch == '_' {
                let mut j = 0usize;
                for c in rest.chars() {
                    if c.is_alphanumeric() || c == '_' {
                        j += c.len_utf8();
                    } else {
                        break;
                    }
                }
                let word = &rest[..j];
                let after = rest[j..].trim_start();
                let color = if is_keyword(self.lang, word) {
                    self.palette.purple
                } else if after.starts_with('(') {
                    match self.lang {
                        Lang::Python => self.palette.cyan,
                        _ => self.palette.blue,
                    }
                } else if word.chars().next().map(|c| c.is_uppercase()).unwrap_or(false) {
                    self.palette.yellow
                } else {
                    self.palette.foreground
                };
                push(&mut spans, word, color);
                i += j;
                continue;
            }

            // One Unicode character of anything else.
            let j = ch.len_utf8();
            push(&mut spans, &rest[..j], self.palette.foreground);
            i += j;
        }

        spans
    }
}

fn is_line_comment(lang: Lang, rest: &str) -> bool {
    match lang {
        Lang::Hash | Lang::Python => rest.starts_with('#'),
        Lang::Slash | Lang::Rust => rest.starts_with("//"),
        _ => false,
    }
}

fn is_keyword(lang: Lang, word: &str) -> bool {
    let rust = [
        "as", "async", "await", "break", "const", "continue", "crate", "dyn", "else", "enum",
        "extern", "false", "fn", "for", "if", "impl", "in", "let", "loop", "match", "mod",
        "move", "mut", "pub", "ref", "return", "self", "Self", "static", "struct", "super",
        "trait", "true", "type", "unsafe", "use", "where", "while",
    ];
    let python = [
        "and", "as", "assert", "async", "await", "break", "class", "continue", "def", "del",
        "elif", "else", "except", "False", "finally", "for", "from", "global", "if", "import",
        "in", "is", "lambda", "None", "nonlocal", "not", "or", "pass", "raise", "return",
        "True", "try", "while", "with", "yield",
    ];
    let slash = [
        "break", "case", "catch", "class", "const", "continue", "default", "do", "else",
        "enum", "export", "extends", "false", "finally", "for", "func", "function", "if",
        "import", "in", "int", "interface", "let", "new", "package", "private", "public",
        "return", "static", "struct", "switch", "this", "throw", "true", "try", "type",
        "typeof", "var", "void", "while", "char", "double", "float", "long", "namespace",
        "template", "typename", "using", "virtual",
    ];
    match lang {
        Lang::Rust => rust.contains(&word),
        Lang::Python => python.contains(&word),
        Lang::Slash => slash.contains(&word),
        _ => false,
    }
}

fn detect_lang(file_name: &str, first_line: &str) -> Lang {
    let base = file_name.rsplit('/').next().unwrap_or(file_name);
    if base == "Makefile" || base == "makefile" || base == "GNUmakefile" {
        return Lang::Hash;
    }
    if first_line.starts_with("#!") {
        if first_line.contains("python") {
            return Lang::Python;
        }
        if first_line.contains("sh") || first_line.contains("bash") || first_line.contains("zsh") {
            return Lang::Hash;
        }
    }
    let ext = base.rsplit('.').next().unwrap_or("");
    if base == ext {
        return Lang::Plain;
    }
    match ext {
        "rs" => Lang::Rust,
        "py" | "pyi" => Lang::Python,
        "c" | "h" | "cpp" | "cc" | "cxx" | "hpp" | "hh" | "hxx" | "java" | "js" | "jsx"
        | "ts" | "tsx" | "mjs" | "cjs" | "go" | "cs" | "kt" | "kts" | "scala" | "swift"
        | "php" => Lang::Slash,
        "sh" | "bash" | "zsh" | "rb" | "pl" | "pm" | "yml" | "yaml" | "toml" | "ini"
        | "cfg" | "conf" => Lang::Hash,
        "html" | "htm" | "xml" | "xhtml" | "svg" => Lang::Html,
        "txt" | "text" | "" => Lang::Plain,
        _ => Lang::Plain,
    }
}
RS
"}

