pub struct Highlighter {
    palette: Palette,
    lang: Lang,
    in_block_comment: bool,
    in_triple: Option<&'static str>,
}

impl Highlighter {
    pub fn new(file_name: &str, first_line: &str, theme: &Theme) -> Self {
        Self {
            palette: palette(theme),
            lang: detect_lang(file_name, first_line),
            in_block_comment: false,
            in_triple: None,
        }
    }

    pub fn highlight_line(&mut self, line: &str) -> Line<'static> {
        if self.lang == Lang::Plain {
            return Line::from(Span::styled(
                line.to_string(),
                Style::default().fg(self.palette.foreground),
            ));
        }
        let spans = self.tokenize(line);
        if spans.is_empty() {
            Line::from(Span::styled(
                String::new(),
                Style::default().fg(self.palette.foreground),
            ))
        } else {
            Line::from(spans)
        }
    }

    fn tokenize(&mut self, line: &str) -> Vec<Span<'static>> {
        let mut spans: Vec<Span<'static>> = Vec::new();
        let bytes = line.as_bytes();
        let mut i = 0usize;

        let push = |spans: &mut Vec<Span<'static>>, text: &str, color: Color| {
            if !text.is_empty() {
                spans.push(Span::styled(text.to_string(), Style::default().fg(color)));
            }
        };

        while i < bytes.len() {
            if self.in_block_comment {
                if let Some(end) = line[i..].find("*/") {
                    let j = i + end + 2;
                    push(&mut spans, &line[i..j], self.palette.comment);
                    i = j;
                    self.in_block_comment = false;
                } else {
                    push(&mut spans, &line[i..], self.palette.comment);
                    break;
                }
                continue;
            }

            if let Some(quote) = self.in_triple {
                if let Some(end) = line[i..].find(quote) {
                    let j = i + end + quote.len();
                    push(&mut spans, &line[i..j], self.palette.green);
                    i = j;
                    self.in_triple = None;
                } else {
                    push(&mut spans, &line[i..], self.palette.green);
                    break;
                }
                continue;
            }

            let rest = &line[i..];

            if self.lang == Lang::Html && rest.starts_with("<!--") {
                if let Some(end) = rest.find("-->") {
                    push(&mut spans, &rest[..end + 3], self.palette.comment);
                    i += end + 3;
                } else {
                    push(&mut spans, rest, self.palette.comment);
                    break;
                }
                continue;
            }

            if (self.lang == Lang::Slash || self.lang == Lang::Rust) && rest.starts_with("/*") {
                if let Some(end) = rest[2..].find("*/") {
                    let j = 2 + end + 2;
                    push(&mut spans, &rest[..j], self.palette.comment);
                    i += j;
                } else {
                    push(&mut spans, rest, self.palette.comment);
                    self.in_block_comment = true;
                    break;
                }
                continue;
            }

            if is_line_comment(self.lang, rest) {
                push(&mut spans, rest, self.palette.comment);
                break;
            }

            if self.lang == Lang::Python && (rest.starts_with("\"\"\"") || rest.starts_with("'''")) {
