                    let j = 3 + end + 3;
                    push(&mut spans, &rest[..j], self.palette.green);
                    i += j;
                } else {
                    push(&mut spans, rest, self.palette.green);
                    self.in_triple = Some(quote);
                    break;
                }
                continue;
            }

