                let mut j = 0usize;
                for c in rest.chars() {
                    if c.is_ascii_alphanumeric() || c == '.' || c == '_' {
                        j += c.len_utf8();
                    } else {
                        break;
                    }
                }
                push(&mut spans, &rest[..j], self.palette.orange);
                i += j;
                continue;
            }

            if ch.is_alphabetic() || ch == '_' {
                let mut j = 0usize;
                for c in rest.chars() {
                    if c.is_alphanumeric() || c == '_' {
                        j += c.len_utf8();
                    } else {
                        break;
                    }
                }
                let word = &rest[..j];
                let after = rest[j..].trim_start();
                let color = if is_keyword(self.lang, word) {
                    self.palette.purple
                } else if after.starts_with('(') {
                    match self.lang {
                        Lang::Python => self.palette.cyan,
                        _ => self.palette.blue,
                    }
                } else if word.chars().next().map(|c| c.is_uppercase()).unwrap_or(false) {
                    self.palette.yellow
                } else {
                    self.palette.foreground
                };
                push(&mut spans, word, color);
                i += j;
                continue;
            }

            // One Unicode character of anything else.
            let j = ch.len_utf8();
            push(&mut spans, &rest[..j], self.palette.foreground);
            i += j;
        }

        spans
    }
}

fn is_line_comment(lang: Lang, rest: &str) -> bool {
    match lang {
        Lang::Hash | Lang::Python => rest.starts_with('#'),
        Lang::Slash | Lang::Rust => rest.starts_with("//"),
        _ => false,
    }
}

fn is_keyword(lang: Lang, word: &str) -> bool {
    let rust = [
        "as", "async", "await", "break", "const", "continue", "crate", "dyn", "else", "enum",
        "extern", "false", "fn", "for", "if", "impl", "in", "let", "loop", "match", "mod",
        "move", "mut", "pub", "ref", "return", "self", "Self", "static", "struct", "super",
        "trait", "true", "type", "unsafe", "use", "where", "while",
    ];
    let python = [
        "and", "as", "assert", "async", "await", "break", "class", "continue", "def", "del",
        "elif", "else", "except", "False", "finally", "for", "from", "global", "if", "import",
        "in", "is", "lambda", "None", "nonlocal", "not", "or", "pass", "raise", "return",
        "True", "try", "while", "with", "yield",
    ];
    let slash = [
        "break", "case", "catch", "class", "const", "continue", "default", "do", "else",
        "enum", "export", "extends", "false", "finally", "for", "func", "function", "if",
        "import", "in", "int", "interface", "let", "new", "package", "private", "public",
        "return", "static", "struct", "switch", "this", "throw", "true", "try", "type",
        "typeof", "var", "void", "while", "char", "double", "float", "long", "namespace",
        "template", "typename", "using", "virtual",
    ];
    match lang {
        Lang::Rust => rust.contains(&word),
        Lang::Python => python.contains(&word),
        Lang::Slash => slash.contains(&word),
