{"command":"cat > src/ui/context_viewer.rs <<'RS'
use super::highlighter::Highlighter;
use crate::args::Theme;
use ratatui::{
    prelude::*,
    widgets::{Block, BorderType, Borders, Paragraph},
};
use std::fs::File;
use std::io::{BufRead, BufReader};

pub fn draw(
    frame: &mut Frame,
    area: Rect,
    file_name: Option<&str>,
    line_number: Option<u64>,
    selected_background: Color,
    theme: &Theme,
) {
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded);

    let Some(file_name) = file_name else {
        frame.render_widget(Paragraph::new("").block(block), area);
        return;
    };
    let Some(line_number) = line_number else {
        frame.render_widget(Paragraph::new("").block(block), area);
        return;
    };

    let lines = read_highlighted(file_name, theme);

    let selected_index = (line_number as usize).saturating_sub(1);
    let half = (area.height as usize) / 2;
    let start = selected_index.saturating_sub(half);
    let mut visible: Vec<Line<'static>> = lines
        .into_iter()
        .skip(start)
        .take(area.height as usize)
        .collect();

    let relative = selected_index - start;
    visible[relative].style = Style::default().bg(selected_background);

    let widget = Paragraph::new(visible).block(block);
    frame.render_widget(widget, area);
}

fn read_highlighted(file_name: &str, theme: &Theme) -> Vec<Line<'static>> {
    let file = File::open(file_name)
        .expect("Failed to create line highlighter");
    let mut reader = BufReader::new(file);
    let mut highlighter: Option<Highlighter> = None;
    let mut lines = Vec::new();

    loop {
        let mut raw_line = String::new();
        let read = reader
            .read_line(&mut raw_line)
            .expect("Not valid UTF-8");
        if read == 0 {
            break;
        }

        let mut text = raw_line.as_str();
        if text.ends_with('\n') {
            text = &text[..text.len() - 1];
            if text.ends_with('\r') {
                text = &text[..text.len() - 1];
            }
        }
        let text_owned = text.replace('\t', "    ");
        if highlighter.is_none() {
            highlighter = Some(Highlighter::new(file_name, &text_owned, theme));
        }
        let line = highlighter
            .as_mut()
            .map(|h| h.highlight_line(&text_owned))
            .unwrap_or_else(|| Line::from(text_owned.clone()));
        lines.push(line);
    }

    lines
}
