use ratatui::{
    prelude::*,
    widgets::{Block, BorderType, Borders, List, ListItem, ListState, Paragraph},
};
use search_popup::{SearchAction, SearchPopup};
use std::io;
use std::sync::mpsc::{self, Receiver, TryRecvError};
use std::time::Duration;

#[derive(Clone, Copy, PartialEq, Eq)]
enum ContextMode {
    None,
    Vertical,
    Horizontal,
}

#[derive(Clone, PartialEq, Eq)]
enum StatusState {
    Searching,
    Finished,
    Error(String),
}

enum Popup {
    Help(HelpPopup),
    Search(SearchPopup),
}

struct SearchTask {
    receiver: Receiver<SearchEvent>,
    finished: bool,
}

pub struct App {
    config: SearchConfig,
    prepared: PreparedSearch,
    opener: FileOpener,
    theme: Theme,

    entries: Vec<FileEntry>,
    found_matches: usize,
    found_files: usize,
    filtered_out: usize,

    selected: Option<(usize, usize)>,
    list_state: ListState,

    context_mode: ContextMode,
    context_size: u16,

    status: StatusState,
    broken: bool,

    pending_prefix: Option<char>,
    pending_display: String,

    popup: Option<Popup>,
    search_task: Option<SearchTask>,
}

impl App {
    pub fn new(
        config: SearchConfig,
        prepared: PreparedSearch,
        opener: FileOpener,
        theme: Theme,
        context_arg: &ContextViewerArg,
    ) -> Self {
        let mut app = Self {
            config,
            prepared,
            opener,
            theme,
            entries: Vec::new(),
            found_matches: 0,
            found_files: 0,
            filtered_out: 0,
            selected: None,
            list_state: ListState::default(),
            context_mode: match context_arg {
                ContextViewerArg::Vertical => ContextMode::Vertical,
                ContextViewerArg::Horizontal => ContextMode::Horizontal,
                ContextViewerArg::None => ContextMode::None,
            },
            context_size: 50,
            status: StatusState::Searching,
            broken: false,
            pending_prefix: None,
            pending_display: String::new(),
            popup: None,
            search_task: None,
        };
        app.start_search();
        app
    }

    fn start_search(&mut self) {
        let (sender, receiver) = mpsc::channel();
        let config = self.config.clone();
        let prepared = self.prepared.clone();
        std::thread::spawn(move || {
            searcher::run_search(config, prepared, sender);
        });
        self.search_task = Some(SearchTask { receiver, finished: false });
    }

    fn trigger_search(&mut self) {
        if self.broken {
            return;
        }
        self.entries.clear();
        self.found_matches = 0;
        self.found_files = 0;
        self.filtered_out = 0;
        self.selected = None;
        self.list_state = ListState::default();
        self.status = StatusState::Searching;
        self.start_search();
    }

    /// Returns false when the search worker disappeared without finishing
    /// (matching the reference behaviour for an invalid pattern).
    fn poll_search(&mut self) -> bool {
        let Some(task) = self.search_task.as_mut() else {
            return true;
        };
        if task.finished {
            return true;
        }
        loop {
            match task.receiver.try_recv() {
                Ok(SearchEvent::File(entry)) => {
                    self.found_matches += entry.matches.len();
                    self.found_files += 1;
                    self.entries.push(entry);
                    if self.selected.is_none() && !self.entries.is_empty() {
                        self.selected = Some((0, 0));
                    }
                }
                Ok(SearchEvent::Finished) => {
                    task.finished = true;
                    if self.status == StatusState::Searching {
                        self.status = StatusState::Finished;
                    }
                    break;
                }
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Disconnected) => {
                    task.finished = true;
                    return false;
                }
            }
        }
        true
    }

    fn total_matches(&self) -> usize {
        self.entries.iter().map(|entry| entry.matches.len()).sum()
    }

    fn selected_global_index(&self) -> usize {
        let Some((file_idx, match_idx)) = self.selected else {
            return 0;
        };
        let before: usize = self.entries[..file_idx.min(self.entries.len())]
            .iter()
            .map(|entry| entry.matches.len())
            .sum();
        before + match_idx + 1
    }

    fn selected_flat_index(&self) -> Option<usize> {
        let (file_idx, match_idx) = self.selected?;
        let mut index = 0usize;
        for (idx, entry) in self.entries.iter().enumerate() {
            if idx == file_idx {
                return Some(index + 1 + match_idx);
            }
            index += 1 + entry.matches.len();
        }
        None
    }

    fn select_by_global(&mut self, global_zero_based: usize) {
        let mut remaining = global_zero_based;
        for (file_idx, entry) in self.entries.iter().enumerate() {
            if remaining < entry.matches.len() {
                self.selected = Some((file_idx, remaining));
                return;
            }
            remaining -= entry.matches.len();
        }
        self.selected = None;
    }

    fn select_next(&mut self) {
        let total = self.total_matches();
        if total == 0 {
            return;
        }
        let current = self.selected_global_index();
        if current < total {
            self.select_by_global(current);
        }
    }

    fn select_previous(&mut self) {
        if self.total_matches() == 0 {
            return;
        }
        let current = self.selected_global_index();
        if current > 1 {
            self.select_by_global(current - 2);
        }
    }

    fn select_next_file(&mut self) {
        let Some((file_idx, _)) = self.selected else { return };
        if file_idx + 1 < self.entries.len() {
            self.selected = Some((file_idx + 1, 0));
        }
    }

    fn select_previous_file(&mut self) {
        let Some((file_idx, _)) = self.selected else { return };
        if file_idx == 0 {
            self.selected = Some((0, 0));
        } else {
            self.selected = Some((file_idx - 1, 0));
        }
    }

    fn select_first(&mut self) {
        if self.total_matches() > 0 {
            self.selected = Some((0, 0));
        }
    }

    fn select_last(&mut self) {
        if let Some(last_idx) = self.entries.len().checked_sub(1) {
            if let Some(last_file) = self.entries.last() {
                if !last_file.matches.is_empty() {
                    self.selected = Some((last_idx, last_file.matches.len() - 1));
                }
            }
        }
    }

    fn filter_selected(&mut self) {
        let Some((file_idx, match_idx)) = self.selected else { return };
        if file_idx >= self.entries.len() || match_idx >= self.entries[file_idx].matches.len() {
            return;
        }
        let global_before = self.selected_global_index() - 1;
        let was_last_in_file = match_idx + 1 == self.entries[file_idx].matches.len();

        self.entries[file_idx].matches.remove(match_idx);
        self.filtered_out += 1;
        if self.entries[file_idx].matches.is_empty() {
            self.entries.remove(file_idx);
        }

        if self.total_matches() == 0 {
            self.selected = None;
            return;
        }
        let target = if was_last_in_file {
            global_before.saturating_sub(1)
        } else {
            global_before
        };
        self.select_by_global(target);
    }

    fn filter_current_file(&mut self) {
        let Some((file_idx, _)) = self.selected else { return };
        if file_idx >= self.entries.len() {
            return;
        }
        let global_first: usize = self.entries[..file_idx]
            .iter()
            .map(|entry| entry.matches.len())
            .sum();
        let removed = self.entries.remove(file_idx);
        self.filtered_out += removed.matches.len();

        if self.total_matches() == 0 {
            self.selected = None;
            return;
        }
        let target = if global_first > 0 { global_first - 1 } else { 0 };
        self.select_by_global(target);
    }

    fn open_current(&mut self) {
        let Some((file_idx, match_idx)) = self.selected else { return };
        let Some(file_entry) = self.entries.get(file_idx) else { return };
        let Some(match_entry) = file_entry.matches.get(match_idx) else { return };
        let file_name = file_entry.file_name.clone();
        let line_number = match_entry.line_number;

        match self.opener.open(&file_name, line_number) {
            Ok(()) => {
                if self.broken {
                    self.status = StatusState::Searching;
                }
            }
            Err(program) => {
                self.status = StatusState::Error(format!(
                    "Failed to open editor '{}'. Is it installed?",
                    program
                ));
                self.broken = true;
            }
        }
    }

    fn sort_by_key(&mut self, requested: SortBy) {
        match self.config.sort {
            Some((current, reverse)) if current == requested => {
                self.config.sort = Some((requested, !reverse));
            }
            _ => {
                self.config.sort = Some((requested, false));
            }
        }
        self.trigger_search();
    }

    fn toggle_context(&mut self, mode: ContextMode) {
        if self.context_mode == mode {
            self.context_mode = ContextMode::None;
        } else {
            self.context_mode = mode;
        }
    }

    fn selected_file_and_line(&self) -> Option<(String, u64)> {
        let (file_idx, match_idx) = self.selected?;
        let entry = self.entries.get(file_idx)?;
        let m = entry.matches.get(match_idx)?;
        Some((entry.file_name.clone(), m.line_number))
    }

    fn draw(&mut self, frame: &mut Frame) {
        let area = frame.area();
        let vertical = Layout::vertical([Constraint::Min(0), Constraint::Length(1)]).split(area);
        let main_area = vertical[0];
        let status_area = vertical[1];

        match self.context_mode {
            ContextMode::None => {
                self.draw_results(frame, main_area);
            }
            ContextMode::Vertical => {
                let chunks = Layout::horizontal([
                    Constraint::Percentage(100 - self.context_size),
                    Constraint::Percentage(self.context_size),
                ])
                .split(main_area);
                self.draw_results(frame, chunks[0]);
                self.draw_context(frame, chunks[1]);
            }
            ContextMode::Horizontal => {
                let chunks = Layout::vertical([
                    Constraint::Percentage(100 - self.context_size),
                    Constraint::Percentage(self.context_size),
                ])
                .split(main_area);
                self.draw_results(frame, chunks[0]);
                self.draw_context(frame, chunks[1]);
            }
        }

        self.draw_status(frame, status_area);

        match self.popup.as_mut() {
            Some(Popup::Help(help)) => help.draw(frame),
            Some(Popup::Search(search)) => search.draw(frame),
            None => {}
        }
    }

    fn selected_background(&self) -> Color {
        match self.theme {
            Theme::Dark => Color::Rgb(58, 58, 58),
            Theme::Light => Color::Rgb(220, 220, 220),
        }
    }

    fn draw_context(&mut self, frame: &mut Frame, area: Rect) {
        let (file_name, line_number) = match self.selected_file_and_line() {
            Some((name, line)) => (Some(name), Some(line)),
            None => (None, None),
        };
        context_viewer::draw(
            frame,
            area,
            file_name.as_deref(),
            line_number,
            self.selected_background(),
            &self.theme,
        );
    }

    fn draw_results(&mut self, frame: &mut Frame, area: Rect) {
        let mut items: Vec<ListItem<'static>> = Vec::new();
        for entry in &self.entries {
            let display_name = entry
                .file_name
                .strip_prefix("./")
                .unwrap_or(&entry.file_name)
                .to_string();
            items.push(ListItem::new(Line::from(Span::styled(
                display_name,
                Style::default().fg(Color::LightMagenta),
            ))));
            for match_entry in &entry.matches {
                items.push(ListItem::new(match_line(match_entry)));
            }
        }

        let selected = self.selected_flat_index();
        self.list_state.select(selected);

        let list = List::new(items)
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .border_type(BorderType::Rounded),
            )
            .highlight_style(Style::default().bg(self.selected_background()));

        frame.render_stateful_widget(list, area, &mut self.list_state);
    }

    fn draw_status(&self, frame: &mut Frame, area: Rect) {
        if area.height == 0 || area.width == 0 {
            return;
        }

        let (state_text, state_bg, message) = match &self.status {
            StatusState::Searching => ("SEARCHING", Color::Rgb(255, 165, 0), String::new()),
            StatusState::Finished => ("FINISHED", Color::Green, self.finished_message()),
            StatusState::Error(message) => ("ERROR", Color::Red, message.clone()),
        };

        let message_style = match self.theme {
            Theme::Dark => Style::default()
                .fg(Color::Rgb(147, 147, 147))
                .bg(Color::Rgb(58, 58, 58)),
            Theme::Light => Style::default(),
        };

        let total = self.total_matches();
        let current = if self.selected.is_some() {
            self.selected_global_index()
        } else {
            0
        };
        let digits = total.to_string().len();
        let fraction = format!("| {:>width$}/{}", current, total, width = digits);
        let fraction_len = fraction.chars().count() as u16;

        let chunks = Layout::horizontal([
            Constraint::Length(12),
            Constraint::Min(0),
            Constraint::Length(3),
            Constraint::Length(fraction_len + 1),
        ])
        .split(area);

        let state_widget = Paragraph::new(state_text)
            .style(
                Style::default()
                    .fg(Color::Black)
                    .bg(state_bg)
                    .add_modifier(Modifier::BOLD),
            )
            .alignment(Alignment::Center);
        frame.render_widget(state_widget, chunks[0]);

        let message_text = if message.is_empty() {
            String::new()
        } else {
            format!(" {}", message)
        };
        let message_widget = Paragraph::new(message_text).style(message_style);
        frame.render_widget(message_widget, chunks[1]);

        let pending_text = format!("{:>2} ", self.pending_display);
        let pending_widget = Paragraph::new(pending_text).style(message_style);
        frame.render_widget(pending_widget, chunks[2]);

        let fraction_widget =
            Paragraph::new(format!("{} ", fraction)).style(message_style);
        frame.render_widget(fraction_widget, chunks[3]);
    }

    fn finished_message(&self) -> String {
        if self.found_matches == 0 {
            return "No matches found.".to_string();
        }
        let match_word = if self.found_matches == 1 { "match" } else { "matches" };
        let file_word = if self.found_files == 1 { "file" } else { "files" };
        if self.filtered_out > 0 {
            format!(
                "Found {} {} in {} {} ({} filtered out).",
                self.found_matches, match_word, self.found_files, file_word, self.filtered_out
            )
        } else {
            format!(
                "Found {} {} in {} {}.",
                self.found_matches, match_word, self.found_files, file_word
            )
        }
    }

    /// Returns true to quit.
    fn handle_key(&mut self, key: KeyEvent) -> bool {
        // Popups claim keys first.
        match self.popup.as_mut() {
            Some(Popup::Help(help)) => {
                if help.handle(key) {
                    self.popup = None;
                }
                return false;
            }
            Some(Popup::Search(search)) => {
                match search.handle(key) {
                    SearchAction::Close => {
                        self.popup = None;
                    }
                    SearchAction::Submit(pattern) => {
                        self.popup = None;
                        self.config.pattern = pattern;
                        self.trigger_search();
                    }
                    SearchAction::None => {}
                }
                return false;
            }
            None => {}
        }

        if key.code == KeyCode::Char('c') && key.modifiers.contains(KeyModifiers::CONTROL) {
            return true;
        }

        match key.code {
            KeyCode::Char(chr) => self.handle_char(chr),
            KeyCode::Esc => {
                if self.pending_prefix.is_some() {
                    self.pending_prefix = None;
                    self.pending_display.clear();
                    return false;
                }
                return true;
            }
            KeyCode::Down => {
                self.clear_pending();
                self.select_next();
            }
            KeyCode::Up => {
                self.clear_pending();
                self.select_previous();
            }
            KeyCode::Right | KeyCode::PageDown => {
                self.clear_pending();
                self.select_next_file();
            }
            KeyCode::Left | KeyCode::PageUp => {
                self.clear_pending();
                self.select_previous_file();
            }
            KeyCode::Home => {
                self.clear_pending();
                self.select_first();
            }
            KeyCode::End => {
                self.clear_pending();
                self.select_last();
            }
            KeyCode::Enter => {
                self.clear_pending();
                self.open_current();
            }
            KeyCode::Delete => {
                self.clear_pending();
                self.filter_selected();
            }
            KeyCode::F(1) => {
                self.clear_pending();
                self.popup = Some(Popup::Help(HelpPopup::new()));
            }
            KeyCode::F(5) => {
                self.clear_pending();
                self.popup = Some(Popup::Search(SearchPopup::new(self.config.pattern.clone())));
            }
            _ => {
                self.clear_pending();
            }
        }
        false
    }

    fn clear_pending(&mut self) {
        self.pending_prefix = None;
        self.pending_display.clear();
    }

    fn handle_char(&mut self, chr: char) -> bool {
        if let Some(prefix) = self.pending_prefix.take() {
            match (prefix, chr) {
                ('g', 'g') => {
                    self.pending_display.clear();
                    self.select_first();
                }
                ('d', 'd') => {
                    self.pending_display.clear();
                    self.filter_selected();
                }
                ('d', 'w') => {
                    self.pending_display.clear();
                    self.filter_current_file();
                }
                _ => {
                    self.pending_display = format!("{}{}", prefix, chr);
                }
            }
            return false;
        }

        match chr {
            'q' => return true,
            'g' | 'd' => {
                self.pending_prefix = Some(chr);
                self.pending_display = format!("{}…", chr);
            }
            '?' => {
                self.pending_display.clear();
                self.popup = Some(Popup::Help(HelpPopup::new()));
            }
            '/' => {
                self.pending_display.clear();
                self.popup = Some(Popup::Search(SearchPopup::new(self.config.pattern.clone())));
            }
            'j' => {
                self.pending_display.clear();
                self.select_next();
            }
            'k' => {
                self.pending_display.clear();
                self.select_previous();
            }
            'l' => {
                self.pending_display.clear();
                self.select_next_file();
            }
            'h' => {
                self.pending_display.clear();
                self.select_previous_file();
            }
            'G' => {
                self.pending_display.clear();
                self.select_last();
            }
            'v' => {
                self.pending_display.clear();
                self.toggle_context(ContextMode::Vertical);
            }
            's' => {
                self.pending_display.clear();
                self.toggle_context(ContextMode::Horizontal);
            }
            '+' => {
                self.pending_display.clear();
                if self.context_size < 80 {
                    self.context_size += 5;
                }
            }
            '-' => {
                self.pending_display.clear();
                if self.context_size > 20 {
                    self.context_size -= 5;
                }
            }
            'n' => {
                self.pending_display.clear();
                self.sort_by_key(SortBy::Path);
            }
            'm' => {
                self.pending_display.clear();
                self.sort_by_key(SortBy::Modified);
            }
            'c' => {
                self.pending_display.clear();
                self.sort_by_key(SortBy::Created);
            }
            'a' => {
                self.pending_display.clear();
                self.sort_by_key(SortBy::Accessed);
            }
            _ => {
                self.pending_display = chr.to_string();
            }
        }
        false
    }
}

fn match_line(match_entry: &crate::ig::MatchEntry) -> Line<'static> {
    let prefix = format!(" {}: ", match_entry.line_number);
    let mut spans: Vec<Span<'static>> = vec![Span::styled(
        prefix,
        Style::default().fg(Color::Green),
    )];

    // Expand tabs (as the reference does, to two spaces) and map the
    // original ranges onto the expanded text. The mapped end keeps the
    // original range length, which reproduces the reference behaviour for
    // matches that themselves contain tab characters.
    let original = &match_entry.text;
    let expanded = original.replace('\t', "  ");

    let map_start = |original_start: usize| -> usize {
        let mut extra = 0usize;
        for (idx, byte) in original.bytes().enumerate() {
            if idx >= original_start {
                break;
            }
            if byte == b'\t' {
                extra += 1;
            }
        }
        original_start + extra
    };

    let red = Style::default().fg(Color::Red);
    let plain = Style::default();

    let mut cursor = 0usize;
    for (start, end) in &match_entry.ranges {
        let expanded_start = map_start(*start);
        let expanded_end = expanded_start + (end - start);
        let expanded_start = expanded_start.min(expanded.len());
        let expanded_end = expanded_end.min(expanded.len());
        if expanded_start > cursor {
            if let Some(text) = expanded.get(cursor..expanded_start) {
                spans.push(Span::styled(text.to_string(), plain));
            }
        }
        if expanded_end > expanded_start {
            if let Some(text) = expanded.get(expanded_start..expanded_end) {
                spans.push(Span::styled(text.to_string(), red));
            }
        }
        cursor = cursor.max(expanded_end);
    }
    if cursor < expanded.len() {
        if let Some(text) = expanded.get(cursor..) {
            spans.push(Span::styled(text.to_string(), plain));
        }
    }

    Line::from(spans)
}

pub fn run(mut app: App) -> anyhow::Result<()> {
    let backend = CrosstermBackend::new(io::stdout());
    let mut terminal = Terminal::new(backend)?;

    enable_raw_mode()?;
    execute!(io::stdout(), EnterAlternateScreen, EnableMouseCapture)?;

    let mut exit = false;
    while !exit {
        if !app.poll_search() {
            break;
        }

        terminal.draw(|frame| app.draw(frame))?;

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if app.handle_key(key) {
                    exit = true;
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    Ok(())
}
RS
