fn is_end_anchored_pattern(pattern: &str, case_insensitive: bool) -> bool {
    let wrapped = format!("(?:{})", pattern);
    let hir_result = regex_syntax::ParserBuilder::new()
        .utf8(false)
        .case_insensitive(case_insensitive)
        .multi_line(false)
        .dot_matches_new_line(false)
        .crlf(false)
        .octal(false)
        .unicode(true)
        .build()
        .parse(&wrapped);
    let Ok(hir) = hir_result else { return false };
    hir_is_end_anchored(&hir)
