fn hir_can_match_empty(hir: &Hir) -> bool {
    match hir.kind() {
        hir::HirKind::Empty | hir::HirKind::Look(_) => true,
        hir::HirKind::Literal(literal) => literal.0.is_empty(),
        hir::HirKind::Class(_) => false,
        hir::HirKind::Capture(capture) => hir_can_match_empty(&capture.sub),
        hir::HirKind::Repetition(repetition) => {
            repetition.min == 0 || hir_can_match_empty(&repetition.sub)
        }
        hir::HirKind::Concat(parts) => parts.iter().all(hir_can_match_empty),
        hir::HirKind::Alternation(parts) => parts.iter().any(hir_can_match_empty),
    }
}

fn hir_is_end_anchored(hir: &Hir) -> bool {
    match hir.kind() {
        hir::HirKind::Look(hir::Look::End) => true,
        hir::HirKind::Capture(capture) => hir_is_end_anchored(&capture.sub),
        hir::HirKind::Repetition(repetition) => {
