use ratatui::{
    prelude::*,
    widgets::{List, ListItem, ListState},
};

#[derive(Default)]
pub struct ScrollOffsetList {
    state: ListState,
    scroll_offset: usize,
}

impl ScrollOffsetList {
    pub fn reset(&mut self) {
        self.state = ListState::default();
        self.scroll_offset = 0;
    }

    pub fn draw(
        &mut self,
        frame: &mut Frame,
        area: Rect,
        items: Vec<ListItem<'static>>,
        selected: Option<usize>,
        block: ratatui::widgets::Block<'static>,
        highlight_style: Style,
    ) {
        if !items.is_empty() {
            if let Some(selected_index) = selected {
                let _first_visible = &items[self.scroll_offset];
                let height = area.height.saturating_sub(2) as usize;
                if height > 0 {
                    if selected_index < self.scroll_offset {
                        self.scroll_offset = selected_index.saturating_sub(1);
                    } else if selected_index >= self.scroll_offset + height {
                        self.scroll_offset = selected_index + 1 - height;
                    }
                }
            }
        }

        self.state.select(selected);
        *self.state.offset_mut() = self.scroll_offset;

        let list = List::new(items)
            .block(block)
            .highlight_style(highlight_style);
        frame.render_stateful_widget(list, area, &mut self.state);
        self.scroll_offset = *self.state.offset();
    }
}
RS
