{"command":"cat > src/ui/search_popup.rs <<'RS'
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::{
    prelude::*,
    widgets::{Block, BorderType, Borders, Clear, Paragraph},
};

pub enum SearchAction {
    None,
    Close,
    Submit(String),
}

pub struct SearchPopup {
    pattern: String,
    cursor: usize,
}

impl SearchPopup {
    pub fn new(pattern: String) -> Self {
        let cursor = pattern.len();
        Self { pattern, cursor }
    }

    pub fn pattern(&self) -> &str {
        &self.pattern
    }

    pub fn cursor(&self) -> usize {
        self.cursor
    }

    fn insert_char(&mut self, chr: char) {
        self.pattern.insert(self.cursor, chr);
        self.cursor += 1;
    }

    fn backspace(&mut self) {
        if !self.pattern.is_empty() {
            self.cursor = self.cursor.saturating_sub(1);
            self.pattern.remove(self.cursor);
        }
    }
    fn delete(&mut self) {
        if self.cursor < self.pattern.len() {
            self.pattern.remove(self.cursor);
        }
    }

    fn move_left(&mut self) {
        self.cursor = self.cursor.saturating_sub(1);
    }

    fn move_right(&mut self) {
        if self.cursor < self.pattern.len() {
            self.cursor += 1;
        }
    }

    pub fn handle(&mut self, key: KeyEvent) -> SearchAction {
        if key.code == KeyCode::Char('c') && key.modifiers.contains(KeyModifiers::CONTROL) {
            return SearchAction::Close;
        }
        match key.code {
            KeyCode::Enter => SearchAction::Submit(self.pattern.clone()),
            KeyCode::Esc | KeyCode::F(5) => SearchAction::Close,
            KeyCode::Char(chr)
                if key.modifiers == KeyModifiers::NONE
                    || key.modifiers == KeyModifiers::SHIFT =>
            {
                self.insert_char(chr);
                SearchAction::None
            }
            KeyCode::Char(_) => SearchAction::None,
            KeyCode::Backspace => { self.backspace(); SearchAction::None }
            KeyCode::Delete => { self.delete(); SearchAction::None }
            KeyCode::Left => { self.move_left(); SearchAction::None }
            KeyCode::Right => { self.move_right(); SearchAction::None }
            _ => SearchAction::None,
        }
    }

    pub fn draw(&self, frame: &mut Frame) {
        let mut area = frame.area();
        area.height = area.height.saturating_sub(1);
        let popup_area = popup_area(area);
        let inner_width = popup_area.width.saturating_sub(2);
        let max_pattern_length = inner_width.saturating_sub(2) as usize;
        let visible_pattern = if self.pattern.len() > max_pattern_length {
            let suffix_start = self.pattern.len() - (max_pattern_length - 1);
            format!(
                "…{}",
                &self.pattern[suffix_start..]
            )
        } else {
            self.pattern.clone()
        };

        let text = format!(" {}", visible_pattern);
        let title_alignment = if " Regex Pattern ".chars().count() as u16 > popup_area.width.saturating_sub(2) {
            Alignment::Left
        } else {
            Alignment::Center
        };
        let block = Block::default()
            .title(" Regex Pattern ")
            .title_alignment(title_alignment)
            .borders(Borders::ALL)
            .border_type(BorderType::Plain)
            .border_style(
                Style::default()
                    .fg(Color::Green)
                    .add_modifier(Modifier::BOLD),
            );
        let widget = Paragraph::new(text)
            .style(Style::default().add_modifier(Modifier::BOLD))
            .block(block);
        frame.render_widget(Clear, popup_area);
        frame.render_widget(widget, popup_area);

        let cursor_x = (popup_area.x + 2 + self.cursor as u16)
            .min(popup_area.x + popup_area.width.saturating_sub(2));
        frame.set_cursor_position((cursor_x, popup_area.y + 1));
    }
}

fn popup_area(area: Rect) -> Rect {
    let vertical = Layout::vertical([
        Constraint::Fill(1),
        Constraint::Length(3),
        Constraint::Fill(1),
    ])
    .split(area);
    let horizontal = Layout::horizontal([
        Constraint::Percentage(25),
        Constraint::Percentage(50),
        Constraint::Percentage(25),
    ])
    .split(vertical[1]);
    horizontal[1]
}
RS
