                    push(&mut spans, &rest[..j], self.palette.green);
                    i += j;
                    continue;
                }
            }
            if rest.starts_with("**") {
                if let Some(end) = rest[2..].find("**") {
                    let j = 2 + end + 2;
                    push(&mut spans, &rest[..j], self.palette.purple);
                    i += j;
                    continue;
                }
            }
            if rest.starts_with('*') {
                if let Some(end) = rest[1..].find('*') {
                    if end > 0 {
                        let j = 1 + end + 1;
                        push(&mut spans, &rest[..j], self.palette.purple);
                        i += j;
                        continue;
                    }
                }
            }
            let ch = rest.chars().next().unwrap();
            push(&mut spans, &rest[..ch.len_utf8()], fg);
            i += ch.len_utf8();
        }
        spans
    }

