    fn tokenize_html(&mut self, line: &str) -> Vec<Span<'static>> {
        let mut spans: Vec<Span<'static>> = Vec::new();
        let mut i = 0usize;
        let fg = self.palette.foreground;
        let mut push = |spans: &mut Vec<Span<'static>>, text: &str, color: Color| {
            if !text.is_empty() {
                spans.push(Span::styled(text.to_string(), Style::default().fg(color)));
            }
        };
        while i < line.len() {
            if self.in_html_comment {
                if let Some(end) = line[i..].find("-->") {
                    push(&mut spans, &line[i..i + end + 3], self.palette.comment);
                    i += end + 3;
                    self.in_html_comment = false;
                } else {
                    push(&mut spans, &line[i..], self.palette.comment);
                    break;
                }
                continue;
            }
            let rest = &line[i..];
            if !self.in_tag {
                if rest.starts_with("<!--") {
                    if let Some(end) = rest.find("-->") {
                        push(&mut spans, &rest[..end + 3], self.palette.comment);
                        i += end + 3;
                    } else {
                        push(&mut spans, rest, self.palette.comment);
                        self.in_html_comment = true;
                        break;
                    }
                    continue;
                }
                if let Some(pos) = rest.find('<') {
                    if pos > 0 {
                        push(&mut spans, &rest[..pos], fg);
                        i += pos;
                        continue;
                    }
                    // At a tag start.
                    let mut j = 1usize;
                    push(&mut spans, "<", fg);
                    if j < rest.len() && (rest.as_bytes()[j] == b'/' || rest.as_bytes()[j] == b'!') {
                        push(&mut spans, &rest[j..j + 1], fg);
                        j += 1;
                    }
                    let name_start = j;
                    while j < rest.len()
                        && (rest.as_bytes()[j].is_ascii_alphanumeric() || rest.as_bytes()[j] == b'-')
                    {
                        j += 1;
                    }
                    if j > name_start {
                        push(&mut spans, &rest[name_start..j], self.palette.red);
                    }
                    self.in_tag = true;
                    i += j;
                    continue;
                }
                push(&mut spans, rest, fg);
                break;
            }
            // Inside a tag.
            let ch = rest.chars().next().unwrap();
            if ch == '>' {
                push(&mut spans, ">", fg);
                self.in_tag = false;
                i += 1;
                continue;
            }
            if ch == '"' || ch == '\'' {
                // attribute value
                let mut j = ch.len_utf8();
                let mut closed = false;
                for (idx, c) in rest.char_indices().skip(1) {
                    if c == ch {
                        j = idx + c.len_utf8();
                        closed = true;
                        break;
                    }
                    j = idx + c.len_utf8();
                }
                let token = &rest[..j];
                let qlen = ch.len_utf8();
                if closed && token.len() >= qlen * 2 {
                    push(&mut spans, &token[..qlen], fg);
                    push(&mut spans, &token[qlen..token.len() - qlen], self.palette.green);
                    push(&mut spans, &token[token.len() - qlen..], fg);
                } else {
                    push(&mut spans, token, self.palette.green);
                }
                i += j;
                continue;
            }
            if ch.is_alphabetic() || ch == '_' {
                let mut j = 0usize;
                for c in rest.chars() {
                    if c.is_alphanumeric() || c == '_' || c == '-' || c == ':' {
                        j += c.len_utf8();
                    } else {
                        break;
                    }
                }
                push(&mut spans, &rest[..j], self.palette.orange);
                i += j;
                continue;
            }
            push(&mut spans, &rest[..ch.len_utf8()], fg);
            i += ch.len_utf8();
        }
        spans
    }

    fn tokenize_shell(&mut self, line: &str) -> Vec<Span<'static>> {
        let mut spans: Vec<Span<'static>> = Vec::new();
        let fg = self.palette.foreground;
        let mut push = |spans: &mut Vec<Span<'static>>, text: &str, color: Color| {
            if !text.is_empty() {
                spans.push(Span::styled(text.to_string(), Style::default().fg(color)));
            }
        };
        let bytes = line.as_bytes();
        let mut i = 0usize;
        while i < bytes.len() {
            let rest = &line[i..];
            if rest.starts_with('#') {
                push(&mut spans, rest, self.palette.comment);
                break;
            }
            let ch = rest.chars().next().unwrap();
            if ch == '"' {
                // double quoted with $var interpolation
                push(&mut spans, "\"", fg);
                i += 1;
                let mut start = i;
                while i < bytes.len() {
                    if bytes[i] == b'"' {
                        if start < i {
                            push(&mut spans, &line[start..i], self.palette.green);
                        }
                        push(&mut spans, "\"", fg);
                        i += 1;
                        start = i;
                        break;
                    }
                    if bytes[i] == b'$' && i + 1 < bytes.len() && (bytes[i + 1].is_ascii_alphabetic() || bytes[i + 1] == b'_' || bytes[i + 1] == b'{') {
                        if start < i {
                            push(&mut spans, &line[start..i], self.palette.green);
                        }
                        push(&mut spans, "$", fg);
                        i += 1;
                        if i < bytes.len() && bytes[i] == b'{' {
                            push(&mut spans, "{", fg);
                            i += 1;
                            let name_start = i;
                            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                                i += 1;
                            }
                            push(&mut spans, &line[name_start..i], self.palette.red);
                            if i < bytes.len() && bytes[i] == b'}' {
                                push(&mut spans, "}", fg);
                                i += 1;
                            }
                        } else {
                            let name_start = i;
                            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                                i += 1;
                            }
                            push(&mut spans, &line[name_start..i], self.palette.red);
                        }
                        start = i;
                        continue;
                    }
                    if bytes[i] == b'\\' && i + 1 < bytes.len() {
                        i += 2;
                        continue;
                    }
                    i += 1;
                }
                continue;
            }
            if ch == '\'' {
                let mut j = 1usize;
                let mut closed = false;
                for (idx, c) in rest.char_indices().skip(1) {
                    if c == '\'' {
                        j = idx + 1;
                        closed = true;
                        break;
                    }
                    j = idx + c.len_utf8();
                }
                let token = &rest[..j];
                if closed && token.len() >= 2 {
                    push(&mut spans, "'", fg);
                    push(&mut spans, &token[1..token.len() - 1], self.palette.green);
                    push(&mut spans, "'", fg);
                } else {
                    push(&mut spans, token, self.palette.green);
                }
                i += j;
                continue;
            }
            if ch == '$' {
                push(&mut spans, "$", fg);
                i += 1;
                if i < bytes.len() && bytes[i] == b'{' {
                    push(&mut spans, "{", fg);
                    i += 1;
                    let name_start = i;
                    while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                        i += 1;
                    }
                    push(&mut spans, &line[name_start..i], self.palette.red);
                    if i < bytes.len() && bytes[i] == b'}' {
                        push(&mut spans, "}", fg);
                        i += 1;
                    }
                } else {
                    let name_start = i;
                    while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                        i += 1;
                    }
                    if name_start < i {
                        push(&mut spans, &line[name_start..i], self.palette.red);
                    }
                }
                continue;
            }
            if ch.is_ascii_digit() {
                let mut j = 0usize;
                for c in rest.chars() {
                    if c.is_ascii_alphanumeric() || c == '.' || c == '_' {
                        j += c.len_utf8();
                    } else {
                        break;
                    }
                }
                push(&mut spans, &rest[..j], self.palette.orange);
                i += j;
                continue;
            }
            if ch.is_alphabetic() || ch == '_' {
                let mut j = 0usize;
                for c in rest.chars() {
                    if c.is_alphanumeric() || c == '_' {
                        j += c.len_utf8();
                    } else {
                        break;
                    }
                }
                let word = &rest[..j];
                let after = rest[j..].trim_start();
                let color = if is_shell_keyword(word) {
                    self.palette.purple
                } else if is_shell_builtin(word) {
                    self.palette.cyan
                } else if after.starts_with('=') {
                    self.palette.red
                } else {
                    fg
                };
                push(&mut spans, word, color);
                i += j;
                continue;
            }
            if ch == '[' || ch == ']' {
                push(&mut spans, &rest[..1], self.palette.cyan);
                i += 1;
                continue;
            }
            push(&mut spans, &rest[..ch.len_utf8()], fg);
            i += ch.len_utf8();
        }
        spans
    }

    fn tokenize_markdown(&mut self, line: &str) -> Vec<Span<'static>> {
        let fg = self.palette.foreground;
        let trimmed = line.trim_start();
        let indent_len = line.len() - trimmed.len();
        let mut spans: Vec<Span<'static>> = Vec::new();
        let mut push = |spans: &mut Vec<Span<'static>>, text: &str, color: Color| {
            if !text.is_empty() {
                spans.push(Span::styled(text.to_string(), Style::default().fg(color)));
            }
        };
        // Headings.
        let hashes = trimmed.chars().take_while(|c| *c == '#').count();
        if hashes >= 1 && hashes <= 6 && trimmed[hashes..].starts_with(' ') {
            if indent_len > 0 {
                push(&mut spans, &line[..indent_len], fg);
            }
            push(&mut spans, &trimmed[..hashes], self.palette.blue);
            push(&mut spans, " ", fg);
            push(&mut spans, &trimmed[hashes + 1..], self.palette.blue);
            return spans;
        }
        // List items.
        if (trimmed.starts_with("- ") || trimmed.starts_with("* ") || trimmed.starts_with("+ "))
            || (trimmed.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false)
                && trimmed.contains(". "))
        {
            push(&mut spans, line, self.palette.red);
            return spans;
        }
        // Inline: links, code, bold/italic.
        let mut i = 0usize;
        let bytes = line.as_bytes();
        while i < bytes.len() {
            let rest = &line[i..];
            if rest.starts_with('[') {
                if let Some(close_bracket) = rest.find("](") {
                    if let Some(close_paren) = rest[close_bracket..].find(')') {
                        let j = close_bracket + close_paren + 1;
                        push(&mut spans, &rest[..j], self.palette.orange);
                        i += j;
                        continue;
                    }
                }
            }
            if rest.starts_with('`') {
                if let Some(end) = rest[1..].find('`') {
                    let j = 1 + end + 1;
                    push(&mut spans, &rest[..j], self.palette.green);
                    i += j;
                    continue;
                }
            }
            if rest.starts_with("**") {
                if let Some(end) = rest[2..].find("**") {
                    let j = 2 + end + 2;
                    push(&mut spans, &rest[..j], self.palette.purple);
                    i += j;
                    continue;
                }
            }
            if rest.starts_with('*') {
                if let Some(end) = rest[1..].find('*') {
                    if end > 0 {
                        let j = 1 + end + 1;
                        push(&mut spans, &rest[..j], self.palette.purple);
                        i += j;
                        continue;
                    }
                }
            }
            let ch = rest.chars().next().unwrap();
            push(&mut spans, &rest[..ch.len_utf8()], fg);
            i += ch.len_utf8();
        }
        spans
    }

