{"command":"cat > src/ui/context_viewer.rs <<'RS'
use super::highlighter::Highlighter;
use crate::args::{ContextViewer as ContextPosition, Theme};
use ratatui::{
    prelude::*,
    widgets::{Block, BorderType, Borders, Paragraph},
};
use std::fs::File;
use std::io::{BufRead, BufReader};

pub struct ContextViewer {
    position: ContextPosition,
    size: u16,
    cached_file_name: Option<String>,
    cached_lines: Vec<Line<'static>>,
}

impl ContextViewer {
    pub fn new(position: ContextPosition) -> Self {
        Self {
            position,
            size: 50,
            cached_file_name: None,
            cached_lines: Vec::new(),
        }
    }

    pub fn toggle_vertical(&mut self) {
        if self.position == ContextPosition::Vertical {
            self.position = ContextPosition::None;
        } else {
            self.position = ContextPosition::Vertical;
        }
    }

    pub fn toggle_horizontal(&mut self) {
        if self.position == ContextPosition::Horizontal {
            self.position = ContextPosition::None;
        } else {
            self.position = ContextPosition::Horizontal;
        }
    }

    pub fn increase_size(&mut self) {
        if self.size < 80 {
            self.size += 5;
        }
    }

    pub fn decrease_size(&mut self) {
        if self.size > 20 {
            self.size -= 5;
        }
    }

    pub fn split(&self, area: Rect) -> (Rect, Option<Rect>) {
        match self.position {
            ContextPosition::None => (area, None),
            ContextPosition::Vertical => {
                let chunks = Layout::horizontal([
                    Constraint::Percentage(100 - self.size),
                    Constraint::Percentage(self.size),
                ])
                .split(area);
                (chunks[0], Some(chunks[1]))
            }
            ContextPosition::Horizontal => {
                let chunks = Layout::vertical([
                    Constraint::Percentage(100 - self.size),
                    Constraint::Percentage(self.size),
                ])
                .split(area);
                (chunks[0], Some(chunks[1]))
            }
        }
    }

    fn lines_for(&mut self, file_name: &str, theme: &Theme) -> &[Line<'static>] {
        let needs_reload = self
            .cached_file_name
            .as_deref()
            .map(|cached| cached != file_name)
            .unwrap_or(true);
        if needs_reload {
            self.cached_lines = Self::read_highlighted(file_name, theme);
            self.cached_file_name = Some(file_name.to_string());
        }
        &self.cached_lines
    }

    fn read_highlighted(file_name: &str, theme: &Theme) -> Vec<Line<'static>> {
        let file = File::open(file_name)
            .expect("Failed to create line highlighter");
        let mut reader = BufReader::new(file);
        let mut highlighter: Option<Highlighter> = None;
        let mut lines = Vec::new();
        let mut raw_line = String::new();
        loop {
            raw_line.clear();
            let read = reader
                .read_line(&mut raw_line)
                .expect("Not valid UTF-8");
            if read == 0 {
                break;
            }

            let mut text = raw_line.as_str();
            if text.ends_with('\n') {
                text = &text[..text.len() - 1];
                if text.ends_with('\r') {
                    text = &text[..text.len() - 1];
                }
            }
            let text_owned: String = text
                .replace('\t', "    ")
                .chars()
                .filter(|chr| !chr.is_control() && *chr != '\u{200b}' && *chr != '\u{feff}')
                .collect();
            if highlighter.is_none() {
                highlighter = Some(Highlighter::new(file_name, &text_owned, theme));
            }
            let line = highlighter
                .as_mut()
                .map(|h| h.highlight_line(&text_owned))
                .unwrap_or_else(|| Line::from(text_owned.clone()));
            lines.push(line);
        }

        lines
    }

    pub fn draw(
        &mut self,
