use crate::ig::MatchEntry;
use ratatui::prelude::*;

pub fn match_line(match_entry: &MatchEntry) -> Line<'static> {
    let prefix = format!(" {}: ", match_entry.line_number);
    let mut spans: Vec<Span<'static>> = vec![Span::styled(
        prefix,
        Style::default().fg(Color::Green),
    )];

    let original = &match_entry.text;
    let expanded: String = original
        .chars()
        .flat_map(|chr| {
            if chr == '\t' {
                Some("  ".to_string())
            } else if chr.is_control() || chr == '\u{200b}' || chr == '\u{feff}' {
                None
            } else {
                Some(chr.to_string())
            }
        })
        .collect();

    let map_start = |upto: usize| -> usize {
        let mut out = 0usize;
        for (idx, chr) in original.char_indices() {
            if idx >= upto {
                break;
            }
            if idx + chr.len_utf8() <= upto {
                out += match chr {
                    '\t' => 2,
                    chr if chr.is_control() || chr == '\u{200b}' || chr == '\u{feff}' => 0,
                    chr => chr.len_utf8(),
                };
            } else {
                // The position lies inside this character: preserve its
                // byte offset within the character for ordinary characters.
                if !chr.is_control() && chr != '\u{200b}' && chr != '\u{feff}' {
                    out += upto - idx;
                }
                break;
            }
        }
        out
    };

    let red = Style::default().fg(Color::Red);
    let plain = Style::default();
    let mut cursor = 0usize;

    for (start, end) in &match_entry.ranges {
        let expanded_start = map_start(*start);
        let mut mapped_len = 0usize;
        for (idx, chr) in original.char_indices() {
            let char_end = idx + chr.len_utf8();
            if idx >= *end {
                break;
            }
            if char_end <= *start {
                continue;
            }
            let overlap = usize::min(char_end, *end) - usize::max(idx, *start);
            mapped_len += match chr {
                '\t' => 1,
                chr if chr.is_control() || chr == '\u{200b}' || chr == '\u{feff}' => 0,
                _ => overlap,
            };
        }
        let expanded_end = expanded_start + mapped_len;

        if expanded_start >= cursor {
            let before = &expanded[cursor..expanded_start];
            spans.push(Span::styled(before.to_string(), plain));
            let matched = &expanded[expanded_start..expanded_end];
            spans.push(Span::styled(matched.to_string(), red));
        } else if expanded_end > cursor {
            if let Some(matched) = expanded.get(cursor..expanded_end) {
                spans.push(Span::styled(matched.to_string(), red));
            }
        }
        cursor = cursor.max(expanded_end);
    }

    if cursor < expanded.len() {
        let after = &expanded[cursor..];
        spans.push(Span::styled(after.to_string(), plain));
    }

    Line::from(spans)
}
