//! A small stateful wrapper around a Ratatui [`List`] that keeps the
//! selected match visible without relying solely on the renderer's
//! built in offset handling.
//!
//! The results in this application are a flat list in which file names
//! and the matches inside those files are separate rows.  When the
//! selection moves upwards out of the viewport, showing the item
//! immediately above the selected match is useful because that item
//! is often the name of the file to which the match belongs.  The
//! custom offset calculation in this module therefore leaves one row
//! above a selection that has scrolled off the top of the viewport,
//! while a selection that scrolls off the bottom is placed on the
//! last visible row.
//!
//! The list itself is stateless with respect to the search results:
//! callers rebuild the items for every frame and pass the currently
//! selected row (if any) to [`ScrollOffsetList::draw`].  This type
//! only remembers the Ratatui list state and the scroll offset that
//! was used for the previous frame.

use ratatui::{
    prelude::*,
    widgets::{List, ListItem, ListState},
};

/// Stateful list renderer with an explicit scroll offset.
#[derive(Default)]
pub struct ScrollOffsetList {
    /// Ratatui's own list state, used for the selected row highlight.
    state: ListState,

    /// Index of the first item rendered in the viewport.
    scroll_offset: usize,

    /// Currently selected item, if the list is not empty.
    selected: Option<usize>,
}

impl ScrollOffsetList {
    /// Creates a list with no selection and a scroll offset of zero.
    pub fn new() -> Self {
        Self::default()
    }

    /// Resets both the selection and scroll offset.
    ///
    /// This is used when a new search replaces the previous set of
    /// results.  Keeping an old offset in that case would make the
    /// first frame of the new search start part-way through an
    /// unrelated list of items.
    pub fn reset(&mut self) {
        self.state = ListState::default();
        self.scroll_offset = 0;
        self.selected = None;
    }

    /// Stores the selected index for the next frame.
    pub fn select(&mut self, selected: Option<usize>) {
        self.selected = selected;
        self.state.select(selected);
    }

    /// Returns the currently selected index, if any.
    pub fn selected(&self) -> Option<usize> {
        self.selected
    }

    /// Returns the scroll offset used for the most recent frame.
    pub fn scroll_offset(&self) -> usize {
        self.scroll_offset
    }

    /// Calculates the number of item rows that fit inside a bordered
    /// list rendered into `area`.
    fn visible_height(area: Rect) -> usize {
        area.height.saturating_sub(2) as usize
    }

    /// Returns the index of the last item that can be shown when the
    /// viewport starts at the current scroll offset.
    fn last_visible_index(&self, height: usize) -> usize {
        if height == 0 {
            self.scroll_offset
        } else {
            self.scroll_offset + height - 1
        }
    }

    /// Checks whether an item is inside the current viewport.
    fn is_visible(&self, index: usize, height: usize) -> bool {
        if height == 0 {
            return false;
        }
        let first = self.scroll_offset;
        let last = self.last_visible_index(height);
        index >= first && index <= last
    }

    /// Moves the offset upwards just enough to reveal `selected`.
    ///
    /// One extra row is kept above the selection where possible.
    /// That row is frequently a file name, and retaining it makes
    /// upward movement through a long list of matches easier to
    /// follow than placing the selection flush with the top border.
    fn scroll_up_to_selected(&mut self, selected: usize) {
        self.scroll_offset = selected.saturating_sub(1);
    }

    /// Moves the offset downwards just enough to reveal `selected`.
    ///
    /// The selected item becomes the final visible row.
    fn scroll_down_to_selected(&mut self, selected: usize, height: usize) {
        if height > 0 {
            self.scroll_offset = selected + 1 - height;
        }
    }

    /// Adjusts the scroll offset for the currently selected item.
    fn ensure_selected_visible(&mut self, items: &[ListItem<'_>], height: usize) {
        let Some(selected_index) = self.selected else {
            return;
        };
        if items.is_empty() || height == 0 {
            return;
        }

        // Touch the item immediately above the viewport before the
        // offset is adjusted.  This mirrors the reference behaviour
        // when a whole file is filtered out while the list is scrolled
        // to the end: the stale offset is not silently clamped here.
        if self.scroll_offset > 0 {
            let _previous_list_items = &items[self.scroll_offset - 1];
        }

        if self.is_visible(selected_index, height) {
            return;
        }
        if selected_index < self.scroll_offset {
            self.scroll_up_to_selected(selected_index);
        } else {
            self.scroll_down_to_selected(selected_index, height);
        }
    }

    /// Draws `items` into `area` with the supplied block and styling.
    pub fn draw(
        &mut self,
        frame: &mut Frame,
        area: Rect,
        items: Vec<ListItem<'static>>,
        selected: Option<usize>,
        block: ratatui::widgets::Block<'static>,
        highlight_style: Style,
    ) {
        self.select(selected);
        let height = Self::visible_height(area);
        self.ensure_selected_visible(&items, height);

        *self.state.offset_mut() = self.scroll_offset;

        let list = List::new(items)
            .block(block)
            .highlight_style(highlight_style);
        frame.render_stateful_widget(list, area, &mut self.state);
        self.scroll_offset = self.state.offset();
    }
}
RS
