            "sh" | "bash" | "zsh" => return Lang::Shell,
            "md" | "markdown" | "mdown" | "mdx" => return Lang::Markdown,
            "rb" | "pl" | "pm" | "yml" | "yaml" | "toml" | "ini" | "cfg" | "conf" => {
                return Lang::Hash
            }
            "html" | "htm" | "xml" | "xhtml" | "svg" => return Lang::Html,
            "txt" | "text" => return Lang::Plain,
            _ => {}
        }
    }
    if first_line.starts_with("#!") {
        if first_line.contains("python") {
            return Lang::Python;
        }
        if first_line.contains("sh") || first_line.contains("bash") || first_line.contains("zsh") {
