struct TextEndVisitor {
    found: bool,
}

impl hir::Visitor for TextEndVisitor {
    type Output = bool;
    type Err = std::convert::Infallible;

    fn finish(self) -> Result<Self::Output, Self::Err> {
        Ok(self.found)
    }

    fn visit_pre(&mut self, hir_node: &Hir) -> Result<(), Self::Err> {
        if let hir::HirKind::Look(hir::Look::End) = hir_node.kind() {
            self.found = true;
        }
        Ok(())
    }
}

pub(crate) fn pattern_has_text_end_anchor(pattern: &str, case_insensitive: bool) -> bool {
    let wrapped = format!("(?:{})", pattern);
    let hir_result = regex_syntax::ParserBuilder::new()
        .utf8(false)
        .case_insensitive(case_insensitive)
        .multi_line(false)
        .dot_matches_new_line(false)
        .crlf(false)
        .octal(false)
        .unicode(true)
        .build()
        .parse(&wrapped);
    let Ok(hir) = hir_result else {
        return false;
    };
    hir::visit::visit(&hir, TextEndVisitor { found: false }).unwrap_or(false)
}
