                out.push(Span::styled(content[start..idx].to_string(), style));
                start = idx;
            }
        }
        if start < content.len() {
            out.push(Span::styled(content[start..].to_string(), style));
        }
    }
    out
}

'''
t=t.replace('pub fn match_line(',helper+'pub fn match_line(')
t=t.replace('    Line::from(spans)\n}','    Line::from(split_emoji_sequences(spans))\n}')
p.write_text(t)

# Context: split spans in each line before Paragraph. In draw, visible lines are Vec<Line>; transform after selected styling? Do it right after lines_for to_vec: map each line.
p=pathlib.Path('src/ui/context_viewer.rs'); t=p.read_text()
old='''        let mut visible: Vec<Line<'static>> = lines
            .into_iter()
            .skip(start)
            .take(area.height as usize)
            .collect();'''
new='''        let mut visible: Vec<Line<'static>> = lines
            .into_iter()
            .skip(start)
            .take(area.height as usize)
            .map(|line| {
                let style = line.style;
                let alignment = line.alignment;
                let mut new_line = Line::from(super::result_list::split_emoji_sequences(line.spans));
                new_line.style = style;
                new_line.alignment = alignment;
                new_line
            })
            .collect();'''
assert old in t; t=t.replace(old,new)
p.write_text(t)
